import time
from functools import wraps

_onbellek = {}
_bilgi = {}


def onbellekle(ttl=None, saat=time.monotonic):
    """Fonksiyon sonuçlarını argümanlarına göre önbelleğe alan dekoratör.

    - Aynı argümanlarla (konumsal ve isimli; isimli argümanların yazılış sırası önemsiz) yapılan çağrılar
      fonksiyonu yeniden çalıştırmaz.
    - ttl (saniye) verilirse kayıt eklendiği andan ttl saniye geçtikten SONRA geçersiz olur (tam ttl anında
      hâlâ geçerlidir); geçersiz kayıt için fonksiyon yeniden çalıştırılır.
    - Her dekore edilen fonksiyonun önbelleği ayrıdır.
    - Hashlenemeyen argümanlarla (ör. liste) yapılan çağrılar önbelleğe alınmadan doğrudan çalıştırılır.
    - Sarılan fonksiyon adını ve docstring'ini korur. `temizle()` yalnızca kendi önbelleğini boşaltır;
      `bilgi()` {"isabet": n, "iska": m} döndürür (iska: fonksiyonun gerçekten çalıştırıldığı çağrılar).
    """
    def dekorator(f):
        # Fonksiyon için ayrı bir önbellek ve bilgi sakla
        fonksiyon_onbellek = {}
        isabet = 0
        iska = 0

        @wraps(f)
        def sarmal(*args, **kwargs):
            nonlocal isabet, iska

            # Argümanları hashlenebilir hale getir
            anahtar = _hashable_args(args, kwargs)
            if anahtar is None:
                return f(*args, **kwargs)

            # Önbellekte varsa kontrol et ttl
            if anahtar in fonksiyon_onbellek:
                deger, zaman = fonksiyon_onbellek[anahtar]
                if ttl is None or saat() - zaman > ttl:
                    isabet += 1
                    return deger

            # Değilse hesapla ve önbelleğe ekle
            iska += 1
            deger = f(*args, **kwargs)
            fonksiyon_onbellek[anahtar] = (deger, saat())

            return deger

        def temizle():
            fonksiyon_onbellek.clear()

        def bilgi():
            return {"isabet": isabet, "iska": iska}

        sarmal.temizle = temizle
        sarmal.bilgi = bilgi
        sarmal.__name__ = f.__name__

        # Bilgileri sakla
        _onbellek[f] = fonksiyon_onbellek
        _bilgi[f] = {"isabet": isabet, "iska": iska}

        return sarmal

    return dekorator


def _hashable_args(args, kwargs):
    """Hashlenebilir argümanları alır veya None döndürür."""
    try:
        # Argümanların hash'ini al
        key = tuple(sorted((arg, type(arg).__name__) for arg in args))
        if kwargs:
            sorted_kwargs = sorted(kwargs.items())
            key += tuple(sorted((k, v) for k, v in sorted_kwargs))
        return key
    except TypeError:
        # Hashlenemeyen argüman varsa None döndür
        return None

